const rows = $input.all().map((item) => item.json || {}).flatMap((row) => Array.isArray(row) ? row : [row]).filter((row) => Object.keys(row).length);
let defaults = {};
try { defaults = $items('Set | Scheduler Runtime Defaults | SchedulerScan')[0]?.json || {}; } catch (_) {}
const defaultTimezone = String(defaults.taskDefaultTimezone || 'Asia/Novosibirsk');
const quietHoursStart = String(defaults.taskQuietHoursStart || '22:00');
const quietHoursEnd = String(defaults.taskQuietHoursEnd || '08:00');
const candidates = [];
for (const row of rows) {
  const storageUsername = String(row.storageUsername || row.userId || row.memoryUserId || '').normalize('NFKC').trim().replace(/^@+/, '').toLowerCase();
  const telegramActorId = String(row.telegramActorId || row.telegramUserId || '').trim();
  const principalKey = String(row.principalKey || '').trim();
  if (!/^actor_[a-f0-9]{32}$/.test(storageUsername)) continue;
  if (!/^\d+$/.test(telegramActorId) || Number(telegramActorId) <= 0) continue;
  if (!/^tgactor_[a-f0-9]{64}$/.test(principalKey)) continue;
  const tenantId = `tenant_${storageUsername}`;
  if (String(row.User || row.tenantId || '').trim() !== tenantId) continue;
  const userId = storageUsername;
  const identity = core.deriveCanonicalIdentity({
    ...row,
    principalKey,
    storageUsername,
    userId,
    memoryUserId: storageUsername,
    tenantId,
    memoryTenantId: tenantId,
    qdrantCollection: `kb_tenant_${storageUsername}`,
    soulId: `chelsea_soul_${storageUsername}`,
    telegramActorId,
    telegramUserId: telegramActorId,
    identitySchemaVersion: 'chelsea_actor_identity_v3',
    identityAuthorityVerified: true,
  });
  const table = core.deriveTenantTable(tenantId);
  candidates.push({ row, ...identity, table });
}
const counts = new Map();
for (const candidate of candidates) counts.set(candidate.tenantId, (counts.get(candidate.tenantId) || 0) + 1);
if (Array.from(counts.values()).some((count) => count !== 1)) {
  const error = new Error('PostgreSQL folder authority contains duplicate canonical task tenant rows');
  error.code = 'duplicate_registry_tenant';
  throw error;
}
return candidates.map(({ row, table, ...identity }) => ({ json: {
  ...identity,
  ownerUserId: identity.userId,
  tenantSafe: table.tenantSafe,
  taskTableName: table.tableName,
  schedulerRegistryRowId: String(row.id || ''),
  schedulerNowIso: new Date().toISOString(),
  taskDefaultTimezone: defaultTimezone,
  taskQuietHoursStart: quietHoursStart,
  taskQuietHoursEnd: quietHoursEnd,
} }));

