const incoming=$input.all().flatMap(item=>{const value=item?.json?.body??item?.json??{};return Array.isArray(value)?value:(Array.isArray(value?.data)?value.data:[value]);});
const clean=value=>String(value??'').normalize('NFKC').trim();
const policies=new Map(incoming.filter(row=>clean(row.principal_id??row.principalId)).map(row=>[clean(row.principal_id??row.principalId),row]));
return users.map(user=>{const policy=policies.get(clean(user.principalKey))||{};return {json:{...user,proactivityMode:clean(policy.proactivity_mode??policy.proactivityMode)||'passive',proactivityPausedUntil:clean(policy.proactivity_paused_until??policy.proactivityPausedUntil),proactivityMorningStart:clean(policy.morning_start??policy.morningStart)||'08:30',proactivityMorningEnd:clean(policy.morning_end??policy.morningEnd)||'10:30',proactivityEveningStart:clean(policy.evening_start??policy.eveningStart)||'20:00',proactivityEveningEnd:clean(policy.evening_end??policy.eveningEnd)||'22:30'}};});
